  "akranes.B.list.7.occupation": "Representative at the Immigration Appeals Board",
  "akranes.B.list.8.occupation": "Director",
  "akranes.B.list.9.occupation": "Construction Technologist",
  "akranes.B.tagline": "This is about Akranes",
  "akranes.C.agenda.0.text": "Viðreisn wants Akranes to become the most desirable municipality in the capital area to live in.",
  "akranes.C.agenda.0.title": "The most desirable town",
  "akranes.C.agenda.1.text": "It must be ensured that every single child in Akranes receives the services they are entitled to.",
  "akranes.C.agenda.1.title": "Children first",
  "akranes.C.agenda.2.text": "The operations of Akraneskaupstaður should be sustainable, transparent, and focused on core services.",
  "akranes.C.agenda.2.title": "Sustainable and transparent operations",
  "akranes.C.agenda.3.text": "Viðreisn wants the town to be a service institution, not a supervisory institution.",
  "akranes.C.agenda.3.title": "The town as a service institution",
  "akranes.C.agenda.4.text": "Older people are an asset, not a burden; respectful services must be ensured.",
  "akranes.C.agenda.4.title": "Older people",
  "akranes.C.agenda.5.text": "The town council should work for residents, not the other way around.",
  "akranes.C.agenda.5.title": "Town council in the service of residents",
  "akranes.C.list.1.bio": "Jón Guðni Guðmundsson is educated as a structural engineer and bridge designer. He leads the Viðreisn list in Akranes in the 2026 municipal elections, marking the first time the party is standing for election to the town council in Akranes.",
  "akranes.C.list.1.occupation": "Structural engineer and bridge designer",
  "akranes.C.list.10.occupation": "Candidate",
  "akranes.C.list.11.occupation": "Candidate",
  "akranes.C.list.12.occupation": "Candidate",
  "akranes.C.list.13.occupation": "Candidate",
  "akranes.C.list.14.occupation": "Candidate",
