  "blaskogabyggd.BSP.agenda.1.title": "Sustainability",
  "blaskogabyggd.BSP.agenda.2.text": "An open and diverse community.",
  "blaskogabyggd.BSP.agenda.2.title": "Community",
  "blaskogabyggd.BSP.list.1.bio": "Anna Greta Ólafsdóttir is a preschool principal and municipal councillor in Bláskógabyggð and lives at Bæjarholt in Reykholt. She served as a compulsory school principal for about five years, first at Reykhólaskóli and later at Flóaskóli, and is a qualified sports scientist with a master's degree in cultural management from Bifröst University. Anna Greta is a full member of the Bláskógabyggð municipal council during the current term and leads the Þ-list in the 2026 local elections, with the ticket seeking to prioritize services for residents, especially children, families, and those who rely on the municipality's diverse services.",
  "blaskogabyggd.BSP.list.1.occupation": "Preschool principal",
  "blaskogabyggd.BSP.list.10.occupation": "Teacher",
  "blaskogabyggd.BSP.list.11.occupation": "Teacher and driving instructor",
  "blaskogabyggd.BSP.list.12.occupation": "School principal",
  "blaskogabyggd.BSP.list.13.occupation": "Chief financial officer and treasurer of Menntaskólinn að Laugarvatni",
  "blaskogabyggd.BSP.list.14.occupation": "Icelandic teacher and director of instruction for FSu in prisons",
  "blaskogabyggd.BSP.list.2.bio": "Valdís María Smáradóttir is a consultant. She is in 2nd place on the Þ-list in Bláskógabyggð for the 2026 local elections.",
  "blaskogabyggd.BSP.list.2.occupation": "Specialist in the advisory division of the Directorate of Labour",
  "blaskogabyggd.BSP.list.3.occupation": "Horticultural farmer and filmmaker",
  "blaskogabyggd.BSP.list.4.occupation": "Education officer",
  "blaskogabyggd.BSP.list.5.occupation": "Teacher, tour guide, municipal councillor",
  "blaskogabyggd.BSP.list.6.occupation": "Project and events manager",
  "blaskogabyggd.BSP.list.7.occupation": "Danish teacher at Framhaldsskólinn í Mosfellsbæ",
  "blaskogabyggd.BSP.list.8.occupation": "Lighting designer and farmer",
  "blaskogabyggd.BSP.list.9.occupation": "Carpenter",
  "blaskogabyggd.BSP.tagline": "Vision — Courage, knowledge, service",
  "blaskogabyggd.BST.agenda.0.text": "Nature conservation and tourism in Þingvallahreppur.",
  "blaskogabyggd.BST.agenda.0.title": "Nature",
  "blaskogabyggd.BST.agenda.1.text": "Good services for residents and support for residential development.",
  "blaskogabyggd.BST.agenda.1.title": "Housing",
  "blaskogabyggd.BST.agenda.2.text": "Innovation and progress for the municipality.",
  "blaskogabyggd.BST.agenda.2.title": "Progress",
  "blaskogabyggd.BST.list.1.bio": "Helgi Kjartansson is a PE teacher and leader of Bláskógabyggð Municipal Council; he leads the T-list in the 2026 local elections in Bláskógabyggð.",
  "blaskogabyggd.BST.list.1.occupation": "PE teacher",
  "blaskogabyggd.BST.list.10.occupation": "Flower farmer",
