  "blaskogabyggd.BST.list.2.occupation": "Engineer",
  "blaskogabyggd.BST.list.4.occupation": "Business graduate",
  "blaskogabyggd.BST.list.5.occupation": "Commercial lawyer",
  "blaskogabyggd.BST.list.6.occupation": "Student teacher",
  "blaskogabyggd.BST.list.7.occupation": "Master carpenter and agricultural scientist",
