  "bolungarvik.BBK.agenda.0.text": "Encourage innovation and a diverse business sector to boost the town's economic growth.",
  "bolungarvik.BBK.agenda.0.title": "Innovation",
  "bolungarvik.BBK.agenda.1.text": "More open governance and greater transparency in the municipality's finances.",
  "bolungarvik.BBK.agenda.1.title": "Transparency",
  "bolungarvik.BBK.agenda.2.text": "Improve infrastructure and services that support residents' daily lives.",
  "bolungarvik.BBK.agenda.2.title": "Infrastructure",
  "bolungarvik.BBK.agenda.3.text": "Repair decades-old potholes in the town's streets and increase the number of trash bins in public areas.",
  "bolungarvik.BBK.agenda.3.title": "Let's fix streets and surroundings",
  "bolungarvik.BBK.agenda.4.text": "Lower charges on residents through improved operations and publish monthly operating reports.",
  "bolungarvik.BBK.agenda.4.title": "Lower charges and transparency",
  "bolungarvik.BBK.agenda.5.text": "Support the development of salmon farming and improve harbor facilities in Bolungarvík.",
  "bolungarvik.BBK.agenda.5.title": "Business life and harbor",
  "bolungarvik.BBK.list.1.occupation": "Candidate",
  "bolungarvik.BBK.list.10.occupation": "Candidate",
  "bolungarvik.BBK.list.11.occupation": "Candidate",
  "bolungarvik.BBK.list.12.occupation": "Candidate",
