  "fjallabyggd.S.agenda.0.text": "Strong welfare and healthcare services for all residents of Fjallabyggð.",
  "fjallabyggd.S.agenda.0.title": "Welfare",
  "fjallabyggd.S.agenda.1.text": "Equal opportunities and social justice as the foundation of policy.",
