  "hvalfjardarsveit.HVA.list.9.occupation": "Seaman",
  "hvalfjardarsveit.HVA.tagline": "A united community — an independent and strong municipality with low taxes, new facilities, and accessible basic services",
  "hvalfjardarsveit.HVB.agenda.0.text": "Increase residents' participation in decision-making and make governance more transparent.",
  "hvalfjardarsveit.HVB.agenda.0.title": "Participatory democracy",
  "hvalfjardarsveit.HVB.agenda.1.text": "Support for a diverse economy and innovation in Hvalfjarðarsveit.",
  "hvalfjardarsveit.HVB.agenda.1.title": "Employment",
  "hvalfjardarsveit.HVB.agenda.2.text": "Ensure healthcare services that serve all residents of the area.",
  "hvalfjardarsveit.HVB.agenda.2.title": "Healthcare services",
  "hvalfjardarsveit.HVB.list.1.bio": "Ragnheiður Sigríður Ragnarsdóttir is in 1st place on the HVB candidate list in Hvalfjarðarsveit in the 2026 municipal elections.",
  "hvalfjardarsveit.HVB.list.1.occupation": "Managing Director",
