  "rangarthingeystra.D.agenda.2.title": "Administration",
  "rangarthingeystra.D.list.1.bio": "Anton Kári Halldórsson is the mayor of Rangárþing eystra and leads the D-list in the 2026 municipal elections; he first became mayor of the municipality after the 2022 elections.",
  "rangarthingeystra.D.list.1.occupation": "Municipal Manager",
  "rangarthingeystra.D.list.10.occupation": "Teacher",
