  "rangarthingeystra.D.list.14.occupation": "Candidate",
  "rangarthingeystra.D.list.2.bio": "Aðalbjörg Rún Ásgeirsdóttir is a farmer at Stóru-Mörk in Rangárþing eystra and is in 2nd place on the D-list in the 2026 municipal elections.",
  "rangarthingeystra.D.list.2.occupation": "Farmer",
  "rangarthingeystra.D.list.3.occupation": "Carpenter",
