  "rangarthingeystra.NRE.tagline": "The new independent list in Rangárþing eystra — Policy 2026–2030",
  "rangarthingytra.D.agenda.0.text": "Building up and advancing the municipality.",
  "rangarthingytra.D.agenda.0.title": "Development",
  "rangarthingytra.D.agenda.1.text": "Support for farmers and business owners in the area.",
  "rangarthingytra.D.agenda.1.title": "Business life",
  "rangarthingytra.D.agenda.2.text": "Responsible and transparent governance.",
  "rangarthingytra.D.agenda.2.title": "Governance",
  "rangarthingytra.D.list.1.bio": "Ingvar Pétur Guðbjörnsson is an information officer and municipal councillor in Rangárþing ytra and leads the D-list in the 2026 municipal elections; he served as assistant to the Minister of Industry from 2013 to 2017.",
  "rangarthingytra.D.list.1.occupation": "Information officer and municipal councillor",
