  "reykjavik.J.list.9.occupation": "Programmer",
  "reykjavik.J.tagline": "Shared infrastructure serves the public — not private interests.",
  "reykjavik.M.agenda.0.text": "Reykjavík’s basic services have been neglected while pet projects have received attention and resources.",
  "reykjavik.M.agenda.0.title": "Turnaround in operations",
  "reykjavik.M.agenda.1.text": "The state of transport in Reykjavík is completely unacceptable and has deteriorated significantly in recent years.",
  "reykjavik.M.agenda.1.title": "Traffic without coercion",
  "reykjavik.M.agenda.2.text": "Human-scale urban planning cannot mean unlimited densification with smaller apartments and a more cramped environment.",
  "reykjavik.M.agenda.2.title": "Planning with rationalism",
  "reykjavik.M.agenda.3.text": "Shortage of preschool places has put families in Reykjavík in an unacceptable situation and constrained their options.",
  "reykjavik.M.agenda.3.title": "Child-friendly city",
  "reykjavik.M.agenda.4.text": "The Icelandic school system has fallen behind comparable countries in academic performance for many reasons.",
  "reykjavik.M.agenda.4.title": "Schools at the forefront",
  "reykjavik.M.agenda.5.text": "The Centre Party wants to protect what is done well in the city’s welfare services.",
  "reykjavik.M.agenda.5.title": "A good city regardless of status",
  "reykjavik.M.agenda.6.text": "Vibrant cultural activity is the core of a flourishing city.",
  "reykjavik.M.agenda.6.title": "Reykjavík, the cultural city",
  "reykjavik.M.list.1.bio": "Ari Edwald is a lawyer and business economist, born in 1964. He completed a law degree and an MBA in the United States. He has held numerous leadership roles, including Managing Director of Samtök atvinnulífsins and CEO of 365 miðlar. He leads the Miðflokkurinn list in Reykjavík.",
  "reykjavik.M.list.1.interests.0": "Parking issues",
  "reykjavik.M.list.1.interests.1": "Preschool system and compulsory school issues",
  "reykjavik.M.list.1.interests.2": "Efficient operation of the city",
  "reykjavik.M.list.1.interests.3": "Opposition to the Borgarlína plans",
  "reykjavik.M.list.1.occupation": "Lawyer, business economist; former CEO of 365 miðlar",
  "reykjavik.M.list.10.occupation": "University student",
  "reykjavik.M.list.11.occupation": "Primary school teacher",
  "reykjavik.M.list.12.occupation": "Visual artist, rapper",
